import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

group_norm_cuda_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

// Kernel to compute mean and variance per group
__global__ void compute_mean_var_kernel(
    const float* __restrict__ input,
    float* __restrict__ mean,
    float* __restrict__ var,
    const int N,
    const int C,
    const int H,
    const int W,
    const int G)
{
    int index = blockIdx.x * blockDim.x + threadIdx.x;
    if (index >= N * G) return;
    int n = index / G;          // batch index
    int g = index % G;          // group index
    int channelsPerGroup = C / G;
    int hw = H * W;
    int groupSize = channelsPerGroup * hw;

    float sum = 0.0f;
    float sumSq = 0.0f;

    // pointer to the start of the batch
    const float* inputPtr = input + n * C * hw;
    int startChannel = g * channelsPerGroup;

    // accumulate sums
    for (int c = 0; c < channelsPerGroup; c++) {
        int channel = startChannel + c;
        const float* channelPtr = inputPtr + channel * hw;
        for (int pix = 0; pix < hw; pix++) {
            float val = channelPtr[pix];
            sum += val;
            sumSq += val * val;
        }
    }

    float meanVal = sum / (float)groupSize;
    float varVal = sumSq / (float)groupSize - meanVal * meanVal;
    mean[index] = meanVal;
    var[index] = varVal;
}

// Kernel to apply GroupNorm using mean/var
__global__ void group_norm_forward_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    const float* __restrict__ mean,
    const float* __restrict__ var,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    const float eps,
    const int N,
    const int C,
    const int H,
    const int W,
    const int G)
{
    int index = blockIdx.x * blockDim.x + threadIdx.x;
    int totalSize = N * C * H * W;
    if (index >= totalSize) return;

    int HW = H * W;
    int c = (index / HW) % C;  
    int n = index / (C * HW);  
    int groupSize = C / G;
    int g = c / groupSize;     
    int groupIndex = n * G + g;

    float meanVal = mean[groupIndex];
    float varVal = var[groupIndex];
    float invStd = rsqrtf(varVal + eps);

    float val = input[index];
    float gamma = weight[c];
    float beta = bias[c];
    float normVal = (val - meanVal) * invStd;
    output[index] = normVal * gamma + beta;
}

torch::Tensor group_norm_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int num_groups,
    float eps)
{
    // input shape: [N, C, H, W]
    int N = input.size(0);
    int C = input.size(1);
    int H = input.size(2);
    int W = input.size(3);

    auto output = torch::zeros_like(input);

    // Alloc space for mean/var: shape [N, G]
    auto mean = torch::zeros({N, num_groups}, torch::dtype(torch::kFloat).device(input.device()));
    auto var  = torch::zeros({N, num_groups}, torch::dtype(torch::kFloat).device(input.device()));

    // Compute mean/var
    int threads = 256;
    int blocks = (N * num_groups + threads - 1) / threads;
    compute_mean_var_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(),
        mean.data_ptr<float>(),
        var.data_ptr<float>(),
        N, C, H, W, num_groups
    );

    // Normalization
    int totalSize = N * C * H * W;
    blocks = (totalSize + threads - 1) / threads;
    group_norm_forward_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        mean.data_ptr<float>(),
        var.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        eps,
        N, C, H, W, num_groups
    );

    return output;
}
""";

group_norm_cpp_source = r"""
torch::Tensor group_norm_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int num_groups,
    float eps);
""";

group_norm = load_inline(
    name="group_norm",
    cpp_sources=group_norm_cpp_source,
    cuda_sources=group_norm_cuda_source,
    functions=["group_norm_forward"],
    verbose=False
)

class ModelNew(nn.Module):
    def __init__(self, num_features: int, num_groups: int):
        super(ModelNew, self).__init__()
        # Replicate GroupNorm learnable params
        self.weight = nn.Parameter(torch.ones(num_features))
        self.bias = nn.Parameter(torch.zeros(num_features))
        self.num_groups = num_groups
        self.eps = 1e-5

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return group_norm.group_norm_forward(
            x, self.weight, self.bias, self.num_groups, self.eps
        )
